# region: gather
def gather(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: intake
def intake(xs, limit=9):
    return [v if v <= limit else limit for v in xs[1:]]

# region: shape
def shape(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: fold
def fold(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: render
def render(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return render(fold(shape(intake(gather(raw)))))

